<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { api, unwrap } from './api/client'
const sections = ['Dashboard', 'Devices', 'Transactions', 'Billing', 'Tariffs']
const page = ref('Dashboard'), lookup = ref(''), tenant = ref(import.meta.env.VITE_DEFAULT_TENANT_ID || '')
const deviceCode = ref(''), transactionId = ref(''), billingId = ref('')
const health: any = useQuery({ queryKey: ['health'], queryFn: async () => (await fetch('/actuator/health')).ok ? 'UP' : 'DOWN', retry: false })
const transactions: any = useQuery({ queryKey: ['transactions'], queryFn: async () => unwrap<any[]>(await api.GET('/api/transactions')), enabled: computed(() => page.value === 'Dashboard' || page.value === 'Transactions') })
const device: any = useQuery({ queryKey: ['device', deviceCode], queryFn: async () => unwrap<any>(await api.GET('/api/devices/{deviceCode}', { params: { path: { deviceCode: deviceCode.value } } })), enabled: computed(() => page.value === 'Devices' && !!deviceCode.value) })
const billing: any = useQuery({ queryKey: ['billing', billingId], queryFn: async () => unwrap<any>(await api.GET('/api/billing-records/{billingRecordId}', { params: { path: { billingRecordId: billingId.value } } })), enabled: computed(() => page.value === 'Billing' && !!billingId.value) })
const tariffList: any = useQuery({ queryKey: ['tariffs', tenant], queryFn: async () => unwrap<any[]>(await api.GET('/api/tariffs', { params: { query: { tenantId: tenant.value } } })), enabled: computed(() => page.value === 'Tariffs' && !!tenant.value) })
const errorText = (e: any) => e?.message || 'Could not load data. Check the backend connection.'
</script>
<template>
<div class="shell"><aside><div class="brand"><span class="logo">V</span><div><b>VoltBridge</b><small>OPERATIONS CONSOLE</small></div></div><nav><button v-for="item in sections" :key="item" :class="{active: page===item}" @click="page=item">{{ item }}</button></nav><div class="side-foot">LIGHTWEIGHT OPERATIONS<br>VoltBridge API · v0.1</div></aside>
<main><header><div><span class="eyebrow">VOLTBRIDGE / {{ page.toUpperCase() }}</span><h1>{{ page }}</h1></div><span class="health"><i :class="health.data==='UP'?'up':''"></i> Backend {{ health.data || 'UNKNOWN' }}</span></header>
<template v-if="page==='Dashboard'"><p class="intro">A live view of charging operations from the VoltBridge backend.</p><div class="cards"><article class="card"><small>ACTIVE TRANSACTIONS</small><strong>{{ transactions.data?.filter((x: any)=>['STARTING','CHARGING','ENDING'].includes(x.status)).length ?? '—' }}</strong><span>Current backend results</span></article><article class="card"><small>COMPLETED TRANSACTIONS</small><strong>{{ transactions.data?.filter((x: any)=>x.status==='COMPLETED').length ?? '—' }}</strong><span>Current backend results</span></article><article class="card"><small>BACKEND HEALTH</small><strong>{{ health.data || 'UNKNOWN' }}</strong><span>Actuator health summary</span></article></div><Panel title="Recent transactions"><ErrorBox v-if="transactions.isError" :message="errorText(transactions.error)"/><p v-else-if="transactions.isLoading">Loading transactions…</p><p v-else-if="!transactions.data?.length" class="empty">No transactions returned by the backend.</p><Rows v-else :items="transactions.data.slice(0,8)" @select="(id:string)=>{transactionId=id;page='Transactions'}"/></Panel></template>
<template v-else-if="page==='Devices'"><Panel title="Device lookup"><form @submit.prevent="deviceCode=lookup.trim()"><label>Device code<input v-model="lookup" placeholder="Enter device code" required></label><button class="primary">Look up device</button></form><ErrorBox v-if="device.isError" :message="errorText(device.error)"/><p v-else-if="device.isLoading">Loading device…</p><pre v-else-if="device.data">{{ JSON.stringify(device.data,null,2) }}</pre><p v-else class="empty">Look up a device by its code. The backend does not expose device inventory.</p></Panel></template>
<template v-else-if="page==='Transactions'"><Panel title="Transaction records"><form @submit.prevent="transactionId=lookup.trim()"><label>Transaction ID<input v-model="lookup" placeholder="Optional transaction UUID"></label><button class="primary">Load transactions</button></form><ErrorBox v-if="transactions.isError" :message="errorText(transactions.error)"/><p v-else-if="transactions.isLoading">Loading transactions…</p><Rows v-else :items="transactions.data||[]" @select="(id:string)=>transactionId=id"/><div v-if="transactionId" class="detail"><h3>Transaction detail</h3><pre>{{ transactionId }}</pre></div></Panel></template>
<template v-else-if="page==='Billing'"><Panel title="Billing record lookup"><form @submit.prevent="billingId=lookup.trim()"><label>Billing record ID<input v-model="lookup" required placeholder="Billing record UUID"></label><button class="primary">Look up billing</button></form><ErrorBox v-if="billing.isError" :message="errorText(billing.error)"/><p v-else-if="billing.isLoading">Loading billing record…</p><pre v-else-if="billing.data">{{ JSON.stringify(billing.data,null,2) }}</pre><p v-else class="empty">Billing is lookup-based; the API does not provide a billing list.</p></Panel></template>
<template v-else><Panel title="Tariff plans"><form @submit.prevent="tenant=tenant.trim()"><label>Tenant ID<input v-model="tenant" required placeholder="Tenant UUID"></label><button class="primary">Load tariffs</button></form><ErrorBox v-if="tariffList.isError" :message="errorText(tariffList.error)"/><p v-else-if="tariffList.isLoading">Loading tariffs…</p><Rows v-else :items="tariffList.data||[]"/><p v-if="!tenant" class="empty">Enter tenant ID to view tariff plans.</p></Panel></template>
<footer>VoltBridge Console · Data shown is returned by the backend</footer></main></div>
</template>
<script lang="ts">
import { defineComponent } from 'vue'
export default { components: {
 Panel: defineComponent({props:{title:String},template:'<section class="panel"><h2>{{title}}</h2><slot/></section>'}),
 ErrorBox: defineComponent({props:{message:String},template:'<div class="error" role="alert">{{message}}</div>'}),
 Rows: defineComponent({props:{items:{type:Array,default:()=>[]}},emits:['select'],template:`<div class="table-wrap"><table><thead><tr><th>Device</th><th>Connector</th><th>Status</th><th>Started</th><th>Amount</th></tr></thead><tbody><tr v-for="(r,i) in items" :key="r.id||i" @click="$emit('select',r.id)"><td>{{r.deviceCode||r.name||r.id}}</td><td>{{r.connectorNo||'—'}}</td><td><span class="tag">{{r.status||r.state||'—'}}</span></td><td>{{r.startedAt||'—'}}</td><td>{{r.totalAmount??'—'}}</td></tr></tbody></table></div>`})
}}
</script>
